"""MA from Backtrader SMA, plotted via chart_indicators (same time keys as OHLCV bars)."""

from __future__ import annotations

import math
from typing import Any

import backtrader as bt
import pandas as pd

import quantcraft.backtest.runtime as rt
from quantcraft.backtest.indicator_series import coerce_chart_time
from quantcraft.inputs import params


PERIOD = params.PERIOD if hasattr(params, "PERIOD") else 45
MAX_OPEN_LONGS = params.MAX_OPEN_LONGS if hasattr(params, "MAX_OPEN_LONGS") else 5
RISK_PERCENT = params.RISK_PERCENT if hasattr(params, "RISK_PERCENT") else 10.0

PERIOD = int(PERIOD)
MAX_OPEN_LONGS = int(MAX_OPEN_LONGS)
RISK_PERCENT = float(RISK_PERCENT)

_sma_by_symbol: dict[str, list[float]] = {}
_bar_times_by_symbol: dict[str, list[Any]] = {}


def _clock_symbol() -> str:
    qc = rt.qc_ohlcv
    by_sym = rt.qc_ohlcv_by_symbol
    if qc is not None and by_sym:
        for sym, q in by_sym.items():
            if q is qc:
                return sym
        if len(by_sym) == 1:
            return next(iter(by_sym.keys()))
    return "UNKNOWN"


def _active_symbol(symbol: str | None) -> str:
    s = (symbol or "").strip().upper()
    if s:
        return s
    c = _clock_symbol()
    return c if c != "UNKNOWN" else "DEFAULT"


def _close0(bar: Any) -> float | None:
    v = bar.close[0]
    if v is None:
        return None
    return float(v)


def _sma_period(bar: Any, period: int) -> float | None:
    acc: list[float] = []
    for i in range(period):
        v = bar.close[i]
        if v is None:
            return None
        acc.append(float(v))
    return sum(acc) / period


def _bar_time_raw(bar: Any) -> Any:
    t0 = bar.t[0]
    return t0 if t0 is not None else bar.get("t")


def _unwrap_strategy(run_result: Any) -> Any | None:
    if not run_result:
        return None
    first = run_result[0]
    if isinstance(first, (list, tuple)) and first:
        return first[0]
    return first


class _BtSmaCollector(bt.Strategy):
    params = (("period", 45),)

    def __init__(self):
        p = max(1, int(self.p.period))
        self.sma = bt.indicators.SMA(self.data.close, period=p)
        self.rows: list[tuple[int, float]] = []

    def next(self):
        v = float(self.sma[0])
        if not math.isfinite(v) or math.isnan(v):
            return
        idx = len(self.data) - 1
        self.rows.append((idx, v))


def on_init() -> None:
    print(f"[smoke_test] PERIOD={PERIOD} | MAX_OPEN_LONGS={MAX_OPEN_LONGS} | RISK_PERCENT={RISK_PERCENT}%")


def on_tick(
    bar_index: int,
    tick_in_bar: int,
    price: float,
    bar: Any,
    fundamentals=None,
    *,
    symbol: str | None = None,
) -> None:
    _ = (bar_index, tick_in_bar, price, bar, fundamentals, symbol)


def on_bar(
    bar_index: int,
    bar: Any,
    fundamentals=None,
    *,
    symbol: str | None = None,
) -> None:
    acc = rt.account
    if acc is None:
        return

    sym = _active_symbol(symbol)
    if sym not in _sma_by_symbol:
        _sma_by_symbol[sym] = []
        _bar_times_by_symbol[sym] = []

    c = _close0(bar)
    ma = _sma_period(bar, PERIOD)

    if ma is not None:
        _sma_by_symbol[sym].append(ma)
        _bar_times_by_symbol[sym].append(_bar_time_raw(bar))

    if ma is None or c is None:
        return

    if c < ma:
        acc.close_all_longs(c, symbol=sym)
        return

    n_open = len(getattr(acc, "_positions", {}))
    if n_open < MAX_OPEN_LONGS and c > ma:
        cash = float(acc.cash)
        if cash <= 0 or c <= 0:
            return
        slots = max(1, MAX_OPEN_LONGS - n_open)
        # RISK_PERCENT % of balance allocated per trade
        risk_fraction = max(0.0, min(RISK_PERCENT, 100.0)) / 100.0
        alloc = min(cash * risk_fraction, cash / slots)
        qty = alloc / c
        if qty * c <= cash + 1e-6:
            acc.open_trade(sym, "long", qty, c)


def on_timer(bar_index, tick_in_bar, price, bar, fundamentals=None, symbol=None):
    pass


def on_finish(bars, symbol=None, bars_by_symbol=None) -> None:
    ci = rt.chart_indicators
    if ci is None:
        return

    # Build a per-symbol map of oldest-first bar lists.
    # Prefer bars_by_symbol (multi-symbol runs); fall back to the single bars list.
    sources: dict[str, list[dict[str, Any]]] = {}
    if bars_by_symbol:
        for sym_key, sym_bars in bars_by_symbol.items():
            if sym_bars:
                sources[str(sym_key).upper()] = list(sym_bars)
    elif bars:
        key = (symbol or _clock_symbol() or "clock").upper()
        sources[key] = list(bars)

    if not sources:
        return

    for sym, bars_oldest_first in sources.items():
        if not bars_oldest_first:
            continue

        df = pd.DataFrame(bars_oldest_first)
        if df.empty or "t" not in df.columns:
            continue

        df["datetime"] = pd.to_datetime(df["t"], utc=True, errors="coerce")
        df = df.dropna(subset=["datetime"]).set_index("datetime")
        for col in ("open", "high", "low", "close", "volume"):
            if col not in df.columns:
                break
            df[col] = pd.to_numeric(df[col], errors="coerce")
        else:
            df = df.dropna(subset=["open", "high", "low", "close"])

            n = len(df)
            if n < 1:
                continue

            period = max(1, min(PERIOD, n))

            cerebro = bt.Cerebro(stdstats=False)
            cerebro.adddata(bt.feeds.PandasData(dataname=df))
            cerebro.addstrategy(_BtSmaCollector, period=period)

            strat = _unwrap_strategy(cerebro.run())
            if strat is None or not getattr(strat, "rows", None):
                continue

            # Map BT SMA values to the same `t` as OHLCV rows (chart alignment).
            points: list[dict[str, Any]] = []
            for idx, v in strat.rows:
                if idx < 0 or idx >= len(bars_oldest_first):
                    continue
                raw_t = bars_oldest_first[idx].get("t")
                ct = coerce_chart_time(raw_t)
                if ct is None:
                    continue
                points.append({"time": ct, "value": float(v)})

            if not points:
                continue

            sym_label = sym if sym not in ("UNKNOWN", "DEFAULT", "") else "clock"
            ci.add(
                points,
                pane="main",
                render="line",
                line_style="solid",
                id=f"bt_sma_{period}_{sym_label}",
                name=f"BT SMA({period}) {sym_label}".strip(),
                color="#ff9800",
                symbol=sym if sym not in ("UNKNOWN", "DEFAULT", "") else None,
            )
